package org.humanjourney.core.progress;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class ProgressCanvasTest {
 @Test void eraSectionsShareOneCanvasAndOneVisibleTab()throws Exception{var v=ProgressSyncTest.initial();assertEquals(2,v.eras().size());assertNotEquals(v.eras().get(0).color(),v.eras().get(1).color());assertEquals(List.of("civilization_progress"),ProgressCanvas.TABS);assertTrue(ProgressCanvas.bounds(v).right()>2000);}
 @Test void crossEraVisualRouteIsDeterministicAndDoesNotAffectState()throws Exception{var v=ProgressSyncTest.initial();var nodes=new HashMap<String,ProgressView.Node>();v.nodes().forEach(n->nodes.put(n.id(),n));var edge=v.connections().getLast();assertEquals(ProgressGraph.EdgeKind.VISUAL,edge.kind());assertEquals(ProgressCanvas.route(edge,nodes,0),ProgressCanvas.route(edge,nodes,0));assertEquals(1810,ProgressCanvas.route(edge,nodes,0).getLast().x());assertEquals(ProgressView.State.LOCKED,nodes.get(edge.to()).state());}
 @Test void multiIncomingAndOutgoingRoutesPreserveAuthorWaypoints()throws Exception{var v=ProgressSyncTest.initial();var nodes=new HashMap<String,ProgressView.Node>();v.nodes().forEach(n->nodes.put(n.id(),n));var incoming=v.connections().stream().filter(e->e.to().equals("human_journey:we_can_stay")).toList();assertEquals(3,incoming.size());for(var e:incoming){var points=ProgressCanvas.route(e,nodes,0);assertEquals(e.route(),points.subList(1,points.size()-1));assertEquals(1480,points.getLast().x());}assertTrue(v.connections().stream().anyMatch(e->e.from().equals("human_journey:we_can_stay")));}
 @Test void zoomAndPanRemainFiniteAndBoundedAtSmallAndLargeSizes()throws Exception{var view=ProgressSyncTest.initial();for(int w:List.of(240,320,640,1280))for(int h:List.of(180,240,720)){var layout=ProgressCanvas.Layout.of(w,h);assertTrue(layout.canvas().width()>0&&layout.canvas().height()>0);assertTrue(layout.details().width()>0&&layout.details().height()>0);var camera=new ProgressCanvas.Viewport();camera.configure(layout.canvas(),ProgressCanvas.bounds(view));camera.fit();for(int i=0;i<100;i++)camera.zoom(8,100,100);assertEquals(2,camera.zoom());for(int i=0;i<100;i++)camera.zoom(-8,100,100);assertEquals(.35,camera.zoom());camera.pan(1e30,-1e30);assertTrue(Double.isFinite(camera.panX())&&Math.abs(camera.panX())<10000);assertTrue(Double.isFinite(camera.panY())&&Math.abs(camera.panY())<10000);}}
 @Test void cursorAnchoredZoomRoundTripAndResizeAreStable(){var camera=new ProgressCanvas.Viewport();camera.configure(new ProgressCanvas.Box(10,20,800,500),new ProgressCanvas.Bounds(-1000,-1000,1000,1000));camera.fit();var point=camera.world(400,250);camera.zoom(1,400,250);var after=camera.world(400,250);assertEquals(point.x(),after.x(),1e-8);assertEquals(point.y(),after.y(),1e-8);double zoom=camera.zoom();camera.configure(new ProgressCanvas.Box(8,40,320,100),new ProgressCanvas.Bounds(-1000,-1000,1000,1000));assertEquals(zoom,camera.zoom());camera.zoom(Double.NaN,1,1);assertEquals(zoom,camera.zoom());}
}
